"""Bounded metadata reader for finalized MP4 files generated by FFmpeg."""
import hashlib
import math
import struct
from pathlib import Path


def boxes(data, start=0):
    end = len(data)
    while start < end:
        if end - start < 8:
            raise ValueError('MP4 box header is incomplete')
        size, kind = struct.unpack_from('>I4s', data, start)
        header = 8
        if size == 1:
            if end - start < 16:
                raise ValueError('MP4 extended box header is incomplete')
            size, header = struct.unpack_from('>Q', data, start + 8)[0], 16
        elif size == 0:
            size = end - start
        if size < header or start + size > end:
            raise ValueError('MP4 box exceeds its parent')
        yield kind, data[start + header:start + size]
        start += size


def one(data, kind):
    matches = [value for name, value in boxes(data) if name == kind]
    if len(matches) != 1:
        raise ValueError('MP4 is missing a unique ' + kind.decode())
    return matches[0]


def timing(data):
    if len(data) >= 20 and data[0] == 0:
        scale, duration = struct.unpack_from('>II', data, 12)
    elif len(data) >= 32 and data[0] == 1:
        scale = struct.unpack_from('>I', data, 20)[0]
        duration = struct.unpack_from('>Q', data, 24)[0]
    else:
        raise ValueError('Unsupported MP4 duration')
    if not scale or not duration:
        raise ValueError('MP4 duration is unavailable')
    return scale, duration


def inspect_mp4(path):
    moov = None
    with Path(path).open('rb') as source:
        end = Path(path).stat().st_size
        offset = 0
        while offset < end:
            source.seek(offset)
            raw = source.read(16)
            if len(raw) < 8:
                raise ValueError('Incomplete MP4')
            size, kind = struct.unpack_from('>I4s', raw)
            header = 8
            if size == 1:
                if len(raw) < 16:
                    raise ValueError('Incomplete MP4')
                size, header = struct.unpack_from('>Q', raw, 8)[0], 16
            elif size == 0:
                size = end - offset
            if size < header or offset + size > end:
                raise ValueError('Invalid MP4 box size')
            if kind == b'moov':
                if moov is not None or size > 64 * 1024 * 1024:
                    raise ValueError('MP4 metadata is duplicate or too large')
                source.seek(offset + header)
                moov = source.read(size - header)
            offset += size
    if moov is None:
        raise ValueError('MP4 is not finalized')
    scale, ticks = timing(one(moov, b'mvhd'))
    tracks = []
    width = height = 0
    for kind, track in boxes(moov):
        if kind == b'mvex':
            raise ValueError('Fragmented MP4 is unsupported for archives')
        if kind != b'trak':
            continue
        mdia = one(track, b'mdia')
        handler = one(mdia, b'hdlr')[8:12]
        if handler not in (b'vide', b'soun'):
            raise ValueError('Unsupported MP4 track')
        timebase, _ = timing(one(mdia, b'mdhd'))
        stsd = one(one(one(mdia, b'minf'), b'stbl'), b'stsd')
        if len(stsd) < 8 or struct.unpack_from('>I', stsd, 4)[0] != 1:
            raise ValueError('Changing MP4 sample descriptions are unsupported')
        entries = list(boxes(stsd, 8))
        if len(entries) != 1:
            raise ValueError('Invalid MP4 sample description')
        tracks.append({'type': handler.decode(), 'codec': entries[0][0].decode('ascii'),
                       'timebase': timebase, 'description': hashlib.sha256(stsd).hexdigest()})
        if handler == b'vide':
            tkhd = one(track, b'tkhd')
            if len(tkhd) < 8:
                raise ValueError('Invalid MP4 video header')
            width, height = (n / 65536 for n in struct.unpack_from('>II', tkhd, len(tkhd) - 8))
    if sum(t['type'] == 'vide' for t in tracks) != 1 or sum(t['type'] == 'soun' for t in tracks) > 1:
        raise ValueError('Archives require one video track and at most one audio track')
    if not (0 < width <= 8192 and 0 < height <= 8192):
        raise ValueError('Invalid MP4 video dimensions')
    return {'durationMs': math.ceil(ticks * 1000 / scale), 'durationSeconds': ticks / scale,
            'tracks': tracks, 'width': int(width), 'height': int(height),
            'hasAudio': any(t['type'] == 'soun' for t in tracks)}
